1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] =>
77	  Object.values(
78	    items.reduce<Record<string, Item[]>>(
79	      (groups, item) => ({
80	        ...groups,
81	        [item.type]: [...(groups[item.type] ?? []), item],
82	      }),
83	      {},
84	    ),
85	  );
86	
87	const basePremiumOfGroup = (items: Item[]): number =>
88	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
89	
90	const policyBasePremium = (items: Item[]): number =>
91	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
92	
93	const CURSED_SURCHARGE_RATE = 0.5;
94	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
95	
96	const HIGH_ENCHANTMENT_THRESHOLD = 5;
97	
98	const isCursed = (item: Item): boolean => item.cursed === true;
99	
100	const isHighlyEnchanted = (item: Item): boolean =>
101	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
102	
103	const NO_SURCHARGE_RATE = 0;
104	
105	const surchargeRateOfItem = (item: Item): number =>
106	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
107	  (isHighlyEnchanted(item)
108	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
109	    : NO_SURCHARGE_RATE);
110	
111	const surchargeOfItem = (item: Item): number =>
112	  basePremiumOfItem(item) * surchargeRateOfItem(item);
113	
114	const sumOfItemSurcharges = (items: Item[]): number =>
115	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
116	
117	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
118	
119	const firstInsuranceSurcharge = (basePremium: number): number =>
120	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
121	
122	const roundPremiumInMHPCOsFavour = (premium: number): number =>
123	  Math.ceil(premium);
124	
125	const LOYALTY_DISCOUNT_RATE = 0.2;
126	const LOYALTY_YEARS_THRESHOLD = 2;
127	const NO_DISCOUNT = 0;
128	
129	const isLoyal = (customer: Customer): boolean =>
130	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
131	
132	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
133	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
134	
135	const quote = (items: Item[], customer: Customer): QuoteResult => {
136	  const basePremium = policyBasePremium(items);
137	  return {
138	    premium: roundPremiumInMHPCOsFavour(
139	      PROCESSING_FEE +
140	        basePremium +
141	        sumOfItemSurcharges(items) +
142	        firstInsuranceSurcharge(basePremium) -
143	        loyaltyDiscount(customer, basePremium),
144	    ),
145	  };
146	};
147	
148	export const runScenario = (scenario: Scenario): ScenarioResult => {
149	  const firstStep = scenario.steps[0] as QuoteStep;
150	  return { results: [quote(firstStep.items, scenario.customer)] };
151	};
